package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveEntry_equals_TriageGen2Test {

    @Test
    public void testEquals_SameInstance() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertTrue("Should return true for the same instance", entry.equals(entry));
    }

    @Test
    public void testEquals_NullObject() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertFalse("Should return false when comparing with null", entry.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        Object other = "not a ZipArchiveEntry";
        assertFalse("Should return false when comparing with a different class type", entry.equals(other));
    }

    @Test
    public void testEquals_SameName() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        assertTrue("Should return true when names are identical", entry1.equals(entry2));
    }

    @Test
    public void testEquals_DifferentName() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("other.txt");
        assertFalse("Should return false when names are different", entry1.equals(entry2));
    }

    @Test
    public void testEquals_BothNamesNull() {
        // Using reflection or a specific constructor if available to simulate null name
        // Since the provided constructor takes a String, we rely on the logic provided.
        // In many implementations, ZipArchiveEntry might allow null via protected constructor or reflection.
        // However, based on the provided equals code, we test the branch: if (name == null) { if (other.name != null) ... }

        ZipArchiveEntry entry1 = createEntryWithNullName();
        ZipArchiveEntry entry2 = createEntryWithNullName();

        assertTrue("Should return true when both names are null", entry1.equals(entry2));
    }

    @Test
    public void testEquals_FirstNameNullSecondNameNotNull() {
        ZipArchiveEntry entry1 = createEntryWithNullName();
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");

        assertFalse("Should return false when first name is null and second is not", entry1.equals(entry2));
    }

    @Test
    public void testEquals_FirstNameNotNullSecondNameNull() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = createEntryWithNullName();

        assertFalse("Should return false when first name is not null and second is null", entry1.equals(entry2));
    }

    /**
     * Helper to create an entry with a null name to test specific branches.
     * Since the public constructor doesn't allow null, we use a workaround 
     * if we were in a real environment, but for this test suite, we simulate the logic.
     */
    private ZipArchiveEntry createEntryWithNullName() {
        // In a real scenario, one might use reflection to set the private field 'name' to null
        // to cover the 'if (name == null)' branch in the provided code.
        try {
            ZipArchiveEntry entry = new ZipArchiveEntry("temp");
            java.lang.reflect.Field nameField = ZipArchiveEntry.class.getDeclaredField("name");
            nameField.setAccessible(true);
            nameField.set(entry, null);
            return entry;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
